19	export const resolveBackgroundColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
20	  if (disabled) return 'transparent';
21	  if (selected) return 'var(--zimm-color-bg-05)';
22	  return 'transparent';
23	};
24	
25	export const resolveTextColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
26	  if (disabled) return 'var(--zimm-color-text-muted)';
27	  if (selected) return 'var(--zimm-color-text-inverse)';
28	  return 'var(--zimm-color-text-default)';
