31	/**
32	 * Recipe for the PDP size chip atom — a single 28x28 (--zimm-scale-700) size option, read
33	 * directly off the size-chip Figma component set (node 40003038:125876) for this exact
34	 * component's dimensions and state list. Four Figma-defined states — Default / Selected /
35	 * Focus / Disabled — resolved by the three `resolveXxxColour` helpers above and the
36	 * `_focusVisible` block below. Hover and Active/pressed are NOT part of that variant set, so
37	 * neither is implemented here — same "don't invent an unspecified visual state" precedent as
38	 * zimmColourSwatchGroup.css.ts's `pageButton` part.
39	 *
40	 * The exact fill/border colour pairing per state is this file's own best-effort reading of the
41	 * "Default / Selected / Disabled" state names against already-established Zimmermann tokens
42	 * (border-forms for a default field-style outline, a text-default fill for the selected state
43	 * mirroring Button's own primary variant, text-muted/border-secondary for disabled mirroring
44	 * Button's/ZimmTextInput's own disabled treatment) — no literal per-state hex breakdown was
45	 * supplied for this component, so this pairing is a reasonable inference from precedent, not a
46	 * pixel-confirmed Figma export. Flag for UI-designer confirmation if it doesn't match.
47	 */
48	export const ZimmSizeChip = {
49	  parts: ['chip'],
50	  baseStyle: (props: ZimmSizeChipStyleProps): Record<string, SystemStyleObject> => ({
51	    chip: {
52	      display: 'flex',
53	      alignItems: 'center',
54	      justifyContent: 'center',
55	      width: 'var(--zimm-scale-700)', // 28px
56	      height: 'var(--zimm-scale-700)', // 28px
57	      border: 'var(--zimm-border-width-default) solid',
58	      borderColor: resolveBorderColour(props),
59	      background: resolveBackgroundColour(props),
60	      color: resolveTextColour(props),
61	      textStyle: 'buttonSm',
62	      padding: 0,
63	      outline: 'none',
64	      cursor: props.disabled ? 'not-allowed' : 'pointer',
65	      _focusVisible: {
66	        outline: 'var(--zimm-focus-ring)',
67	        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
68	      },
69	    },
70	  }),
71	};
