/**
 * Border colour precedence: disabled > selected > default — same "no state stacking" shape as
 * zimmTextInput.css.ts's resolveBorderColour. Default and Disabled both resolve to
 * 'transparent' rather than a real colour: Figma's Default/Disabled variants (nodes
 * 40003038:125875 / :125873) render as plain text with no box at all, so the always-present
 * `border` shorthand on `chip` below is made invisible rather than removed outright — the same
 * "transparent border avoids a layout shift" idiom zimmColourSwatch.css.ts's `swatch` part
 * uses for its own unselected state.
 */
export const resolveBorderColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent'; // Figma Disabled (…125873): no box, muted text only
  if (selected) return 'var(--zimm-color-border-focus)'; // Figma Selected (…125874): outline-only box
  return 'transparent'; // Figma Default (…125875): no box, plain text
};

/**
 * Background is transparent in every branch: Figma's Selected variant (…125874) is an
 * outline-only box — border present, no fill — so no state here ever paints a background.
 * Kept as an explicit disabled/selected/default cascade, matching the other two resolvers'
 * shape, rather than collapsed to a bare `'transparent'` return, so a future Figma revision
 * that does introduce a fill only has to change one branch's value.
 */
export const resolveBackgroundColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent';
  if (selected) return 'transparent'; // outline-only box — was var(--zimm-color-bg-05); Figma has no fill
  return 'transparent';
};

/**
 * Text colour precedence: disabled > selected > default. Selected does NOT get an inverted
 * (white) treatment — Figma's Selected variant (…125874) keeps the same dark default text
 * colour as Default and only adds the outline box via resolveBorderColour above.
 */
export const resolveTextColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'var(--zimm-color-text-muted)';
  if (selected) return 'var(--zimm-color-text-default)'; // no inversion — outline-only box, not filled
  return 'var(--zimm-color-text-default)';
};

